import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        String bookId = registerBook("Reserve Available");

        reserve(bookId, registerMember())
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reservations_form_a_queue_and_are_listed_in_order() throws Exception {
        String bookId = registerBook("Reserve Queue");
        borrow(bookId, registerMember());
        String first = registerMember();
        String second = registerMember();

        reserve(bookId, first)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(1));
        reserve(bookId, second)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
