import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional
public class ReserveBookService implements ReserveBookUseCase {

    private final LoadBookPort loadBookPort;
    private final LoadMemberPort loadMemberPort;
    private final LoadReservationsPort loadReservationsPort;
    private final SaveReservationPort saveReservationPort;

    public ReserveBookService(LoadBookPort loadBookPort, LoadMemberPort loadMemberPort,
                              LoadReservationsPort loadReservationsPort, SaveReservationPort saveReservationPort) {
        this.loadBookPort = loadBookPort;
        this.loadMemberPort = loadMemberPort;
        this.loadReservationsPort = loadReservationsPort;
        this.saveReservationPort = saveReservationPort;
    }

    @Override
    public PlacedReservation reserveBook(ReserveBookCommand command) {
        // 대출과 같은 책 잠금을 잡아서, 줄을 읽고 붙이는 사이에 대출이나 다른 예약이 끼어들지 못하게 한다.
        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        book.ensureReservable();

        List<Reservation> queue = loadReservationsPort.loadActiveReservations(book.getId());
        if (queue.stream().anyMatch(r -> r.getMemberId().equals(command.memberId()))) {
            throw new AlreadyReservedException(book.getId(), command.memberId());
        }
        Reservation reservation = Reservation.place(book.getId(), command.memberId());
        saveReservationPort.saveReservation(reservation);
        return new PlacedReservation(reservation.getId(), queue.size() + 1);
    }
}
