package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        String bookId = registerBook("Reserve Available");

        reserve(bookId, registerMember())
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reservations_form_a_queue_and_are_listed_in_order() throws Exception {
        String bookId = registerBook("Reserve Queue");
        borrow(bookId, registerMember());
        String first = registerMember();
        String second = registerMember();

        reserve(bookId, first)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(1));
        reserve(bookId, second)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void same_member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook("Reserve Twice");
        borrow(bookId, registerMember());
        String member = registerMember();
        reserve(bookId, member).andExpect(status().isCreated());

        reserve(bookId, member)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void returned_book_is_reserved_for_the_head_of_the_queue_until_borrowed() throws Exception {
        String bookId = registerBook("Reserve Handoff");
        String loanId = borrow(bookId, registerMember());
        String head = registerMember();
        String next = registerMember();
        reserve(bookId, head).andExpect(status().isCreated());
        reserve(bookId, next).andExpect(status().isCreated());

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        loan(bookId, next)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));

        loan(bookId, head).andExpect(status().isCreated());

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(next))
                .andExpect(jsonPath("$[0].position").value(1));
    }

    @Test
    void reserving_a_discarded_book_returns_409() throws Exception {
        String bookId = registerBook("Reserve Discarded");
        borrow(bookId, registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanIdOf(bookId))).andExpect(status().isOk());
        mockMvc.perform(post("/books/{bookId}/discard", bookId)).andExpect(status().isOk());

        reserve(bookId, registerMember())
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_with_unknown_book_or_member_returns_404() throws Exception {
        reserve(UUID.randomUUID().toString(), registerMember()).andExpect(status().isNotFound());

        String bookId = registerBook("Reserve Unknown Member");
        borrow(bookId, registerMember());
        reserve(bookId, UUID.randomUUID().toString()).andExpect(status().isNotFound());
    }

    // 반납 테스트에서 대출 ID 를 다시 찾기 위한 용도. 책 하나당 대출은 하나만 만든다.
    private String loanIdOf(String bookId) throws Exception {
        String body = mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andReturn().getResponse().getContentAsString();
        return lastLoanIds.get(bookId);
    }

    private final Map<String, String> lastLoanIds = new java.util.HashMap<>();

    private org.springframework.test.web.servlet.ResultActions reserve(String bookId, String memberId) throws Exception {
        return mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("memberId", memberId))));
    }

    private org.springframework.test.web.servlet.ResultActions loan(String bookId, String memberId) throws Exception {
        return mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId))));
    }

    private String borrow(String bookId, String memberId) throws Exception {
        String body = loan(bookId, memberId)
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String loanId = objectMapper.readTree(body).get("loanId").asText();
        lastLoanIds.put(bookId, loanId);
        return loanId;
    }

    private String registerMember() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"강태현\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String body = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }
}
